import XCTest
import UIKit
@testable import Spendy

final class PWAMigrationTests: XCTestCase {
    @MainActor func testEveryMappedIconExistsOnIOS() throws {
        let url = try XCTUnwrap(Bundle(for: Self.self).url(forResource: "pwa-icon-symbols-v1", withExtension: "json"))
        let symbols = try JSONDecoder().decode([String].self, from: Data(contentsOf: url))
        for symbol in symbols {
            XCTAssertNotNil(UIImage(systemName: symbol), "Missing native icon: \(symbol)")
        }
    }
    // Generated by SpendyWebsite/scripts/migration-native-fixture.mjs.
    // The fixture is synthetic and never contains a user's financial records.
    @MainActor func testBrowserConvertedBackupImportsAndSurvivesNativeReexport() throws {
        let directory = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: directory) }
        let fixtureURL = try XCTUnwrap(Bundle(for: Self.self).url(forResource: "pwa-migration-v1", withExtension: "json"))
        let data = try Data(contentsOf: fixtureURL)
        let store = ExpenseStore(storageURL: directory.appendingPathComponent("source.json"), startsServices: false)
        XCTAssertTrue(store.importJSONData(data: data))
        XCTAssertEqual(store.userName, "Migration Test")
        XCTAssertEqual(store.transactions.count, 4)
        XCTAssertEqual(store.accounts.count, 2)
        XCTAssertEqual(store.categories.count, 3)
        XCTAssertEqual(store.subscriptions.count, 1)
        XCTAssertEqual(store.currencyCode, "INR")
        XCTAssertEqual(store.currencySymbol, "₹")
        XCTAssertEqual(store.appearanceMode, .dark)
        XCTAssertEqual(store.balance(for: "bank"), 1377.76, accuracy: 0.000001)
        XCTAssertEqual(store.balance(for: "cash"), 90, accuracy: 0.000001)
        XCTAssertEqual(store.transactions.first { $0.title == "Pay day" }?.notes, "Keep this note 👋")
        let expectedInstant = try XCTUnwrap(ISO8601DateFormatter().date(from: "2026-11-02T12:35:00Z"))
        XCTAssertEqual(store.transactions.first { $0.title == "Lunch" }?.date, expectedInstant)
        let fractional = try XCTUnwrap(store.transactions.first { $0.title == "Pay day" })
        XCTAssertEqual(fractional.date.timeIntervalSince1970, 1793536496.789, accuracy: 0.001)
        let subscription = try XCTUnwrap(store.subscriptions.first)
        XCTAssertTrue(subscription.autoDeduct)
        XCTAssertTrue(subscription.isTrial)
        XCTAssertEqual(store.transactions.first { $0.title == "Music" }?.subscriptionId?.lowercased(), subscription.id.uuidString.lowercased())
        let category = try XCTUnwrap(store.categories.first { $0.id == "food" })
        XCTAssertEqual(category.label, "Coffee & Lunch")
        XCTAssertEqual(category.sfSymbol, "fork.knife")
        XCTAssertTrue(category.isHidden)
        XCTAssertEqual(store.customFolders.first?.name, "My essentials")
        XCTAssertEqual(store.budget.categoryBudgets["food"], 50)
        let nativeData = try XCTUnwrap(store.exportJSONData())
        let restored = ExpenseStore(storageURL: directory.appendingPathComponent("restored.json"), startsServices: false)
        XCTAssertTrue(restored.importJSONData(data: nativeData))
        XCTAssertEqual(restored.accounts, store.accounts)
        XCTAssertEqual(restored.subscriptions, store.subscriptions)
        // The native encoder uses whole-second ISO dates. The initial import
        // must keep milliseconds; account values and links must survive export.
        XCTAssertEqual(restored.balance(for: "bank"), store.balance(for: "bank"))
        XCTAssertEqual(restored.transactions.first { $0.title == "Music" }?.subscriptionId, store.transactions.first { $0.title == "Music" }?.subscriptionId)
        let nativeObject = try XCTUnwrap(JSONSerialization.jsonObject(with: nativeData) as? [String: Any])
        XCTAssertNil(nativeObject["_spendyMigration"])
        store.flushPendingSave()
        restored.flushPendingSave()
    }
}
